package dev.industrialtechnology.test;
import java.util.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;
import cpw.mods.fml.common.*;import cpw.mods.fml.common.event.FMLInitializationEvent;import cpw.mods.fml.common.eventhandler.SubscribeEvent;import cpw.mods.fml.common.gameevent.TickEvent;
import dev.industrialtechnology.bag.*;import dev.industrialtechnology.core.*;
import net.minecraft.entity.player.*;import net.minecraft.world.*;import net.minecraft.init.*;import net.minecraft.item.*;import net.minecraft.inventory.*;import net.minecraft.item.crafting.CraftingManager;import net.minecraft.nbt.*;import net.minecraft.server.MinecraftServer;import net.minecraftforge.common.util.FakePlayer;

@Mod(modid="industrialtech_bag_checks",name="Disposable Bag Checks",version="1",dependencies="required-after:industrialtech")
public final class BagServerChecks {
    private static final UUID OWNER=UUID.fromString("d4e8eb17-1c45-4f46-90aa-270000000001");
    private final List<String> report=new ArrayList<String>();private int ticks,failed;private boolean done;private WorldServer w;private FakePlayer p;
    interface Test{void run()throws Exception;}
    private static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
    private void test(String n,Test t){try{t.run();report.add("PASS: "+n);}catch(Throwable e){failed++;report.add("FAIL: "+n+" :: "+e);IndustrialTechnology.log.error(n,e);}}
    @Mod.EventHandler public void init(FMLInitializationEvent e){if(Boolean.getBoolean("industrialtech.bagTest"))FMLCommonHandler.instance().bus().register(this);}
    private FakePlayer player(UUID id){return new FakePlayer(w,new com.mojang.authlib.GameProfile(id,"BagTester")){@Override public void sendPlayerAbilities(){}@Override public void addChatMessage(net.minecraft.util.IChatComponent c){}};}
    private BagContainer open(int color){for(int i=0;i<36;i++)p.inventory.mainInventory[i]=null;p.inventory.setItemStack(null);p.inventory.currentItem=0;p.inventory.mainInventory[0]=new ItemStack(BagRegistry.bag,1,color);return BagContainer.open(p,false);}
    private void clear(BagInventory b){for(int i=0;i<104;i++)b.setInventorySlotContents(i,null);}
    private ItemStack craft(int color){InventoryCrafting inv=new InventoryCrafting(new Container(){@Override public boolean canInteractWith(EntityPlayer p){return true;}},3,3);for(int i=0;i<9;i++)inv.setInventorySlotContents(i,i==4?new ItemStack(Blocks.ender_chest):new ItemStack(i%2==0?Item.getItemFromBlock(Blocks.wool):Items.leather,1,i%2==0?color:0));return CraftingManager.getInstance().findMatchingRecipe(inv,w);}
    private ItemStack dye(ItemStack input,int color){InventoryCrafting inv=new InventoryCrafting(new Container(){@Override public boolean canInteractWith(EntityPlayer p){return true;}},2,2);inv.setInventorySlotContents(0,input);inv.setInventorySlotContents(3,new ItemStack(Items.dye,1,15-color));return CraftingManager.getInstance().findMatchingRecipe(inv,w);}
    @SubscribeEvent public void tick(TickEvent.ServerTickEvent e){if(done||e.phase!=TickEvent.Phase.END||!MinecraftServer.getServer().isDedicatedServer()||++ticks<70)return;w=MinecraftServer.getServer().worldServerForDimension(0);p=player(OWNER);if(new File("bag-phase1.done").exists()){restart();finish("restart");}else{initial();finish("initial");}}
    private void initial(){
        test("All sixteen color recipes craft nonstacking bags and dye recipes select the exact matching color",()->{for(int c=0;c<16;c++){ItemStack s=craft(c);check(BagRegistry.valid(s)&&s.getItemDamage()==c&&s.getMaxStackSize()==1,"craft "+c);ItemStack recolor=dye(new ItemStack(BagRegistry.bag,1,(c+1)%16),c);check(BagRegistry.valid(recolor)&&recolor.getItemDamage()==c,"dye "+c);}});
        test("Each color offers exactly 104 storage slots in the original 13 by 8 screen layout",()->{BagContainer c=open(0);check(c.inventorySlots.size()==140&&c.bag.getSizeInventory()==104,"slot count");Slot s=c.getSlot(103);check(s.xDisplayPosition==228&&s.yDisplayPosition==131,"last slot");check(c.getSlot(104).yDisplayPosition==152&&c.getSlot(139).yDisplayPosition==210,"player layout");});
        test("Two same-color bags share one canonical inventory while different colors remain separate",()->{BagData d=BagData.get(w);check(d.inventory(OWNER,1)==d.inventory(OWNER,1),"not canonical");d.inventory(OWNER,1).setInventorySlotContents(103,new ItemStack(Items.emerald,7));check(d.inventory(OWNER,1).getStackInSlot(103).stackSize==7&&d.inventory(OWNER,2).getStackInSlot(103)==null,"color leak");});
        test("Different players never share a color inventory",()->{BagInventory other=BagData.get(w).inventory(UUID.fromString("d4e8eb17-1c45-4f46-90aa-270000000002"),1);check(other.getStackInSlot(103)==null&&!other.isUseableByPlayer(p),"owner leak");});
        test("Shift-click inserts and extracts actual stacks with custom item NBT intact",()->{BagContainer c=open(3);clear(c.bag);ItemStack s=new ItemStack(Items.diamond,23);s.setStackDisplayName("Saved diamonds");p.inventory.mainInventory[9]=s;c.transferStackInSlot(p,104);check(p.inventory.mainInventory[9]==null&&c.bag.getStackInSlot(0).stackSize==23&&"Saved diamonds".equals(c.bag.getStackInSlot(0).getDisplayName()),"insert");c.transferStackInSlot(p,0);check(c.bag.getStackInSlot(0)==null&&p.inventory.mainInventory[8].stackSize==23,"extract");});
        test("Open bag rejects click, shift-click, throw and number-key movement of its protected hotbar slot",()->{BagContainer c=open(4);ItemStack held=p.getHeldItem();for(int mode:new int[]{0,1,2,3,4,6}){c.slotClick(c.lockedSlot,0,mode,p);check(p.getHeldItem()==held&&p.inventory.getItemStack()==null,"mode "+mode);}c.bag.setInventorySlotContents(0,new ItemStack(Items.iron_ingot,10));c.slotClick(0,0,2,p);check(p.getHeldItem()==held&&c.bag.getStackInSlot(0).stackSize==10,"number swap");check(c.transferStackInSlot(p,c.lockedSlot)==null,"shift lock");});
        test("Nested bags are rejected through cursor, shift-click and drag paths without deleting them",()->{BagContainer c=open(5);clear(c.bag);ItemStack second=new ItemStack(BagRegistry.bag,1,6);p.inventory.mainInventory[9]=second;check(c.transferStackInSlot(p,104)==null&&p.inventory.mainInventory[9]==second,"nested shift");p.inventory.mainInventory[9]=null;p.inventory.setItemStack(second);c.slotClick(0,0,0,p);check(p.inventory.getItemStack()==second&&c.bag.getStackInSlot(0)==null,"nested cursor");c.slotClick(-999,0,5,p);c.slotClick(0,1,5,p);c.slotClick(1,1,5,p);c.slotClick(-999,2,5,p);check(p.inventory.getItemStack()==second&&c.bag.getStackInSlot(0)==null&&c.bag.getStackInSlot(1)==null,"nested drag");p.inventory.setItemStack(null);});
        test("Ordinary left/right clicks and drag distribution preserve exact item counts",()->{BagContainer c=open(6);clear(c.bag);p.inventory.setItemStack(new ItemStack(Items.gold_ingot,11));c.slotClick(0,1,0,p);check(c.bag.getStackInSlot(0).stackSize==1&&p.inventory.getItemStack().stackSize==10,"right click");c.slotClick(-999,0,5,p);c.slotClick(1,1,5,p);c.slotClick(2,1,5,p);c.slotClick(-999,2,5,p);check(c.bag.getStackInSlot(1).stackSize==5&&c.bag.getStackInSlot(2).stackSize==5&&p.inventory.getItemStack()==null,"drag count");});
        test("Full storage leaves inputs untouched and partially full stacks merge without loss",()->{BagContainer c=open(7);for(int i=0;i<104;i++)c.bag.setInventorySlotContents(i,new ItemStack(Blocks.stone,64));p.inventory.mainInventory[9]=new ItemStack(Blocks.stone,20);check(c.transferStackInSlot(p,104)==null&&p.inventory.mainInventory[9].stackSize==20,"full");c.bag.getStackInSlot(0).stackSize=60;c.transferStackInSlot(p,104);check(c.bag.getStackInSlot(0).stackSize==64&&p.inventory.mainInventory[9].stackSize==16,"partial merge");});
        test("Unstackable items and item metadata keep their ordinary stack limits",()->{BagContainer c=open(8);clear(c.bag);p.inventory.mainInventory[9]=new ItemStack(Items.iron_sword,1,17);c.transferStackInSlot(p,104);check(c.bag.getStackInSlot(0).stackSize==1&&c.bag.getStackInSlot(0).getItemDamage()==17,"tool changed");});
        test("Changing the held bag or hotbar selection invalidates the open container",()->{BagContainer c=open(9);p.inventory.currentItem=1;check(!c.canInteractWith(p)&&c.slotClick(0,0,0,p)==null,"selection");p.inventory.currentItem=0;p.inventory.mainInventory[0]=new ItemStack(BagRegistry.bag,1,10);check(!c.canInteractWith(p),"color change");});
        test("Death and a replacement player retain their personal bag storage",()->{BagInventory b=BagData.get(w).inventory(OWNER,10);b.setInventorySlotContents(44,new ItemStack(Items.redstone,31));p.isDead=true;FakePlayer replacement=player(OWNER);check(b.isUseableByPlayer(replacement)&&BagData.get(replacement.worldObj).inventory(OWNER,10).getStackInSlot(44).stackSize==31,"death lost contents");p.isDead=false;});
        test("Other dimensions resolve to the same overworld-owned bag data",()->{WorldServer end=MinecraftServer.getServer().worldServerForDimension(1);check(end!=null&&BagData.get(end)==BagData.get(w),"dimension bank mismatch");});
        test("Recoloring selects another storage channel without erasing either color's contents",()->{BagData d=BagData.get(w);d.inventory(OWNER,11).setInventorySlotContents(42,new ItemStack(Items.diamond,19));ItemStack s=dye(new ItemStack(BagRegistry.bag,1,11),12);check(s.getItemDamage()==12&&d.inventory(OWNER,11).getStackInSlot(42).stackSize==19&&d.inventory(OWNER,12).getStackInSlot(42)==null,"recolor changed contents");});
        test("NBT preserves slot 103, owner, color and exact custom item tags",()->{BagData d=BagData.get(w);ItemStack s=new ItemStack(Items.gold_ingot,13);s.setStackDisplayName("Last slot survives");d.inventory(OWNER,13).setInventorySlotContents(103,s);NBTTagCompound n=new NBTTagCompound();d.writeToNBT(n);BagData copy=new BagData();copy.readFromNBT(n);check(ItemStack.areItemStacksEqual(s,copy.inventory(OWNER,13).getStackInSlot(103)),"NBT mismatch");});
        test("GUI routing refuses nonbags and invalid color metadata without opening remote tiles",()->{open(0);p.inventory.mainInventory[0]=new ItemStack(Items.stick);check(IndustrialTechnology.proxy.getServerGuiElement(8,p,w,1000000,80,1000000)==null,"nonbag GUI");p.inventory.mainInventory[0]=new ItemStack(BagRegistry.bag,1,99);check(BagContainer.open(p,false)==null,"invalid color GUI");});
        test("Save writes independent personal/color data for genuine JVM restart",()->{BagInventory b=BagData.get(w).inventory(OWNER,15);ItemStack s=new ItemStack(Items.emerald,37);s.setStackDisplayName("Restart bag");b.setInventorySlotContents(103,s);b.markDirty();w.mapStorage.saveAllData();Files.write(Paths.get("bag-phase1.done"),Arrays.asList("saved"),StandardCharsets.UTF_8);});
    }
    private void restart(){test("Real JVM restart restores all shared-color storage including last-slot NBT",()->{BagData d=BagData.get(w);ItemStack s=d.inventory(OWNER,15).getStackInSlot(103);check(s!=null&&s.stackSize==37&&s.getDisplayName().equals("Restart bag"),"saved contents");check(d.inventory(OWNER,1).getStackInSlot(103).stackSize==7&&d.inventory(OWNER,11).getStackInSlot(42).stackSize==19,"other colors lost");});}
    private void finish(String phase){done=true;try{report.add("Failed: "+failed);Files.write(Paths.get("bag-"+phase+".txt"),report,StandardCharsets.UTF_8);}catch(Exception e){throw new RuntimeException(e);}MinecraftServer.getServer().initiateShutdown();}
}
